<?php $heading='Lamaran Saya';$subtitle='Pantau status dan perkembangan setiap kesempatan yang kamu ajukan.';$kicker='PERJALANAN KARIER · LAMARAN';$headingAction='<a class="button secondary" href="'.e(url('lamaran')).'">Muat ulang status</a>';require ROOT.'/app/Views/components/heading.php';?><div class="tabs"><a class="<?= query('status')===''?'active':'' ?>" href="<?= e(url('lamaran')) ?>">Semua <span><?= count($semuaLamaran) ?></span></a><?php foreach(['Lamaran Terkirim','Diproses','Wawancara','Diterima','Ditolak'] as $s):?><a class="<?= query('status')===$s?'active':'' ?>" href="<?= e(url('lamaran',['status'=>$s])) ?>"><?= e($s) ?> <span><?= count(array_filter($semuaLamaran,fn($a)=>$a['statusLamaran']===$s)) ?></span></a><?php endforeach;?></div><p class="muted small">Status diperbarui otomatis setiap <?= APP['refresh_seconds'] ?> detik selama halaman ini terbuka.</p>
<div class="stack"><?php foreach($daftarLamaran as $item):?><article class="card application-card"><div class="application-top"><div class="application-info"><div class="company-avatar"><?= e(initials($item['namaPerusahaan'])) ?></div><div><h2><?= e($item['namaLowongan']) ?></h2><p><?= e($item['namaPerusahaan']) ?></p><div class="job-meta"><span><?= icon('location') ?><?= e($item['lokasiPenempatan']) ?></span><span><?= e($item['jenisPekerjaan']) ?> · <?= e($item['modeKerja']) ?></span></div><div class="tags"><small>Diajukan <?= tanggal($item['tanggalMelamar']) ?></small><?= badge($item['statusLamaran']) ?></div></div></div><?php require ROOT.'/app/Views/components/timeline.php';?><a class="button secondary" href="<?= e(url('lamaran/detail',['id'=>$item['idLamaran']])) ?>">Lihat Detail <?= icon('arrow') ?></a></div><?php if($item['lowonganDihapus']||$item['perusahaanDihapus']):?><div class="note">Lowongan tidak lagi tersedia. Riwayat lamaran tetap disimpan.</div><?php endif;?><?php $next=$jadwalLamaran[(int)$item['idLamaran']][0]??null;if($next&&!in_array($item['statusLamaran'],['Ditolak','Diterima'],true)):?><div class="schedule-strip"><?= icon('calendar') ?><span><strong>Jadwal seleksi:</strong> <?= e($next['judul']) ?> · <?= tanggal($next['waktu'],'d M Y, H:i') ?> WIB</span><a href="<?= e(url('kalender',['bulan'=>substr($next['waktu'],0,7)])) ?>">Lihat jadwal <?= icon('arrow') ?></a></div><?php endif;?></article><?php endforeach;?></div>
<?php if(!$daftarLamaran):?><div class="card empty-state"><div class="empty-icon"><?= icon('file') ?></div><h2><?= e($pesan) ?></h2><p>Mulai dengan menemukan lowongan yang sesuai dengan minatmu.</p><a class="button" href="<?= e(url('lowongan')) ?>">Jelajahi Lowongan <?= icon('arrow') ?></a></div><?php endif;?>
